package com.smartdairy.service; import com.smartdairy.entity.Delivery; import com.smartdairy.repository.DeliveryRepository; import java.sql.SQLException; import java.util.List;
public class DeliveryService{private final DeliveryRepository repo=new DeliveryRepository(); public void save(Delivery d)throws Exception{validate(d);repo.save(d);} public void update(Delivery d)throws Exception{if(d.getId()<=0)throw new IllegalArgumentException("Invalid delivery id");validate(d);repo.update(d);} public void delete(int id)throws Exception{repo.delete(id);} public List<Delivery> findAll()throws Exception{return repo.findAll();} private void validate(Delivery d){if(d.getOrderId()<=0)throw new IllegalArgumentException("Valid order is required");if(d.getDeliveryPerson()==null||d.getDeliveryPerson().trim().isEmpty())throw new IllegalArgumentException("Delivery person is required");}}
